export type CapturedTurnWriter = (
  input: CapturedTurnWriteInput,
) => Promise<StewardResult<CapturedTurnWriteResult>>;

export interface TurnHealthReport {
  status: ThreadRecord["status"]["turnState"];
  issues: StewardIssue[];
