    input.targetEventKey ??
    targetMetadata.targetEventKey ??
    `pi:${sessionId ?? sessionFilePath ?? "unknown-session"}:runtime-note:${createContentFingerprint({
      note: input.note,
      createdAt,
      sessionEntryId: input.sessionEntryId,
    }).slice(0, 16)}`;

  targetMetadata.targetEventKey = targetEventKey;

  return {
    actor: {
      actorId: createStableId("actor", { runtime: "pi", role: "runtime_note" }),
      actorType: "runtime",
      displayName: "PI Runtime",
      targetMetadata: {
        runtime: "pi",
        rawType: "runtime_note",
      },
    },
    messageKind: "runtime_event",
    createdAt,
    parts: [
      buildPart(
        1,
        "runtime_note",
        typeof input.note === "string" ? { note: input.note } : structuredClone(input.note),
      ),
    ],
    targetMetadata,
    targetEventKey,
  };
}

  const threadId = createThreadId();

  return withSerializedThreadOperation(threadId, async () => {
    const created = await input.store.createThread({
      thread: createThreadRecord({
        threadId,
        target,
        createdAt,
      }),
      targetRef: {
        runtime: target.runtime,
        sessionId: target.sessionId,
        sessionFilePath: target.sessionFilePath,
      },
    });
    if (!created.ok) {
      return created;
    }

    const importedMessages: MessageRecord[] = [];
    const structuralIssues = cloneIssues(importPlan.value.issues);
    const collectedIssues: StewardIssue[] = [];
    const runtimeContext = importRuntimeContext(runtimeInput, importPlan.value.sessionId);

    for (const entry of importPlan.value.entries) {
      const mapped = mapPiMessageEnd({
        message: entry.message,
        ctx: runtimeContext,
        imported: true,
        sessionEntryId: entry.sessionEntryId,
      });
      if (!mapped.ok) {
        const importRecord = buildImportRecord({
          importPlan: importPlan.value,
          importedAt: createdAt,
          importedMessages,
          status: "failed",
          issues: mergeIssues(
            decorateImportIssues({
              issues: structuralIssues,
              sourceRange: importedRange(importedMessages),
              threadId: created.value.threadId,
              sessionId: importPlan.value.sessionId,
            }),
            collectedIssues,
            mapped.issues,
          ),
        });
        await recordFailedImport({
          store: input.store,
          thread: created.value,
          importRecord,
          expectedSourceRevision: importedMessages.at(-1)?.sourceRevision,
        });
        return mapped;
      }

      const activity = {
        ...mapped.value,
        createdAt: mapped.value.createdAt ?? entry.timestamp,
      };

      const captured = await captureFinalizedActivityInCurrentThreadOperation({
        store: input.store,
        threadId: created.value.threadId,
        activity,
      });

      if (!captured.ok) {
        const importRecord = buildImportRecord({
          importPlan: importPlan.value,
          importedAt: createdAt,
          importedMessages,
          status: "failed",
          issues: mergeIssues(
            decorateImportIssues({
              issues: structuralIssues,
              sourceRange: importedRange(importedMessages),
              threadId: created.value.threadId,
              sessionId: importPlan.value.sessionId,
            }),
            collectedIssues,
            mapped.issues,
            captured.issues,
          ),
        });
        await recordFailedImport({
          store: input.store,
          thread: created.value,
          importRecord,
          expectedSourceRevision: importedMessages.at(-1)?.sourceRevision,
        });
        return captured;
      }

      importedMessages.push(structuredClone(captured.value.message));
      const messageRange = createSourceRange(captured.value.message.sourceOrder);
      collectedIssues.push(
        ...cloneIssues(mapped.issues).map((issue) => ({
          ...issue,
          threadId: created.value.threadId,
          targetRuntime: "pi" as const,
          targetSessionId: importPlan.value.sessionId,
          sourceRange: issue.sourceRange ?? messageRange,
        })),
        ...cloneIssues(captured.issues).map((issue) => ({
          ...issue,
          sourceRange: issue.sourceRange ?? messageRange,
        })),
      );
    }

    const snapshot = await input.store.openThread(created.value.threadId);
    if (!snapshot.ok) {
      const importRecord = buildImportRecord({
        importPlan: importPlan.value,
        importedAt: createdAt,
        importedMessages,
        status: "failed",
        issues: mergeIssues(
          decorateImportIssues({
            issues: structuralIssues,
            sourceRange: importedRange(importedMessages),
            threadId: created.value.threadId,
            sessionId: importPlan.value.sessionId,
          }),
          collectedIssues,
          snapshot.issues,
        ),
      });
      await recordFailedImport({
        store: input.store,
        thread: created.value,
        importRecord,
        expectedSourceRevision: importedMessages.at(-1)?.sourceRevision,
      });
      return snapshot;
    }

    const importStatus: ImportRecord["status"] =
      collectedIssues.length > 0 || structuralIssues.length > 0 ? "partial" : "complete";
    const importedSourceRange = importedRange(importedMessages);
    const importIssues = mergeIssues(
      decorateImportIssues({
        issues: structuralIssues,
        sourceRange: importedSourceRange,
        threadId: created.value.threadId,
        sessionId: importPlan.value.sessionId,
      }),
      collectedIssues,
    );

    if (importStatus === "partial") {
      if (snapshot.value.turns.length > 0) {
        const nextTurns = repairNeededTurns(
          snapshot.value.turns,
          sourceRangesFromIssues(importIssues, importedSourceRange),
          snapshot.value.thread.sourceRevision,
          createdAt,
        );
        const finalized = await finalizeThreadTurnState({
          store: input.store,
          thread: snapshot.value.thread,
          status: "repair_needed",
          turns: nextTurns,
        });
        if (!finalized.ok) {
          return finalized;
        }
      } else {
        const finalized = await finalizeThreadTurnState({
          store: input.store,
          thread: snapshot.value.thread,
          status: "repair_needed",
        });
        if (!finalized.ok) {
          return finalized;
        }
      }
    } else if (snapshot.value.thread.status.turnState !== "ready") {
      const finalized = await finalizeThreadTurnState({
        store: input.store,
        thread: snapshot.value.thread,
        status: "ready",
      });
      if (!finalized.ok) {
        return finalized;
      }
    }

    const importRecord = buildImportRecord({
      importPlan: importPlan.value,
      importedAt: createdAt,
      importedMessages,
      status: importStatus,
      issues: importIssues,
    });

    const recordedImport = await input.store.recordImport(created.value.threadId, importRecord);
    if (!recordedImport.ok) {
      return recordedImport;
    }

    const finalSnapshot = await input.store.openThread(created.value.threadId);
    if (!finalSnapshot.ok) {
      return finalSnapshot;
    }

    const baseHealth = checkTurnHealth(finalSnapshot.value);
    const health: TurnHealthReport =
      importStatus === "partial"
        ? {
            ...baseHealth,
            status: "repair_needed",
            issues: sortIssues(mergeIssues(baseHealth.issues, importRecord.issues)),
          }
        : baseHealth;

    return ok({
      thread: recordedImport.value,
      importedMessages: importedMessages.length,
      importedSourceRange,
      importRecord,
      health,
    }, importRecord.issues);
  });
}

import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { fail, mergeIssues, ok, type StewardIssue, type StewardResult } from "../domain/errors.js";
import { createFixtureId, createSourceRange } from "../domain/ids.js";
import type { FixtureRecord, ImportRecord, TurnRepairStatus } from "../domain/records.js";
import { attachExistingPiSession, type AttachPiSessionInput } from "./import-service.js";
import { checkMaintenanceReadiness } from "./turn-service.js";
import { FileThreadStore } from "../store/file-thread-store.js";
import type { ThreadSnapshot, ThreadStore } from "../store/thread-store.js";

export interface CreateRealSessionFixtureInput {
  store: ThreadStore;
  source:
    | { type: "managed_thread"; threadId: string }
    | Pick<AttachPiSessionInput, "activeLeafId" | "sessionManager"> & {
        type: "pi_session";
        sessionFilePath: string;
        sessionId?: string;
      };
  fixtureName?: string;
  now?: () => Date;
}

function nowIso(now: (() => Date) | undefined): string {
  return (now ?? (() => new Date()))().toISOString();
}

function cloneIssues(issues: readonly StewardIssue[] | undefined): StewardIssue[] {
  return (issues ?? []).map((issue) => ({
    ...issue,
    sourceRange: issue.sourceRange ? { ...issue.sourceRange } : undefined,
  }));
}

function latestImportRecord(snapshot: ThreadSnapshot): ImportRecord | undefined {
  return [...snapshot.imports]
    .sort((left, right) => left.importedAt.localeCompare(right.importedAt))
    .at(-1);
}

function snapshotSourceRange(snapshot: ThreadSnapshot) {
  const firstMessage = snapshot.messages[0];
  const lastMessage = snapshot.messages.at(-1);
  if (!firstMessage || !lastMessage) {
    return undefined;
  }

  return createSourceRange(firstMessage.sourceOrder, lastMessage.sourceOrder);
}

function fixtureRepairStatus(snapshot: ThreadSnapshot): TurnRepairStatus {
  const readiness = checkMaintenanceReadiness(snapshot);
  if (readiness.status === "ready") {
    return "ready";
  }

  if (
    snapshot.thread.status.turnState === "repair_failed" ||
    readiness.blockers.some((issue) => issue.code === "TURN_REPAIR_WRITE_FAILED")
  ) {
    return "repair_failed";
  }

  return "repair_needed";
}

function fixtureIssues(
  sourceType: FixtureRecord["sourceType"],
  snapshot: ThreadSnapshot,
): StewardIssue[] | undefined {
  const readiness = checkMaintenanceReadiness(snapshot);
  const issues =
    sourceType === "pi_session"
      ? mergeIssues(readiness.blockers, latestImportRecord(snapshot)?.issues)
      : mergeIssues(readiness.blockers);

  return issues.length > 0 ? cloneIssues(issues) : undefined;
}

function buildFixtureRecord(
  input: CreateRealSessionFixtureInput,
  snapshot: ThreadSnapshot,
  createdAt: string,
): FixtureRecord {
  const sourceRange = snapshotSourceRange(snapshot);
  const importRecord = latestImportRecord(snapshot);
  const issues = fixtureIssues(input.source.type, snapshot);

  return {
    fixtureId: createFixtureId(),
    fixtureName: input.fixtureName,
    sourceType: input.source.type,
    sourceThreadId: input.source.type === "managed_thread" ? input.source.threadId : undefined,
    sourceSessionId:
      input.source.type === "pi_session"
        ? input.source.sessionId ?? snapshot.thread.target.sessionId ?? importRecord?.sourceSessionId
        : undefined,
    sourcePath:
      input.source.type === "pi_session"
        ? input.source.sessionFilePath
        : undefined,
    sourceRange,
    createdAt,
    threadShape: "thread_shaped_data",
    importStatus: input.source.type === "pi_session" ? importRecord?.status : undefined,
    repairStatus: fixtureRepairStatus(snapshot),
    status: "available",
    issues,
  };
}

function stringifyIssues(issues: readonly StewardIssue[]): string {
  return issues
    .map((issue) => `${issue.code}: ${issue.message}${issue.cause ? ` (${issue.cause})` : ""}`)
    .join("; ");
}

function wrapFixtureFailure(
  input: CreateRealSessionFixtureInput,
  issues: readonly StewardIssue[],
): StewardResult<FixtureRecord> {
  const sourceLabel =
    input.source.type === "managed_thread"
      ? `managed thread ${input.source.threadId}`
      : `PI session ${input.source.sessionFilePath}`;

  return fail(
    {
      code: "FIXTURE_CREATE_FAILED",
      message: `Failed to create fixture from ${sourceLabel}.`,
      threadId: input.source.type === "managed_thread" ? input.source.threadId : undefined,
      targetRuntime: input.source.type === "pi_session" ? "pi" : undefined,
      targetSessionId: input.source.type === "pi_session" ? input.source.sessionId : undefined,
      cause: stringifyIssues(issues),
    },
    ...cloneIssues(issues),
  );
}

async function loadManagedThreadSnapshot(
  input: CreateRealSessionFixtureInput & {
    source: Extract<CreateRealSessionFixtureInput["source"], { type: "managed_thread" }>;
  },
): Promise<StewardResult<ThreadSnapshot>> {
  return input.store.openThread(input.source.threadId);
}

async function loadPiSessionSnapshot(
  input: CreateRealSessionFixtureInput & {
    source: Extract<CreateRealSessionFixtureInput["source"], { type: "pi_session" }>;
  },
): Promise<StewardResult<ThreadSnapshot>> {
  const tempProjectDir = await mkdtemp(join(tmpdir(), "context-steward-fixture-"));

  try {
    const tempStore = new FileThreadStore(join(tempProjectDir, ".context-steward"));
    const attached = await attachExistingPiSession({
      store: tempStore,
      target: {
        runtime: "pi",
        sessionId: input.source.sessionId,
        sessionFilePath: input.source.sessionFilePath,
      },
      sessionFilePath: input.source.sessionFilePath,
      activeLeafId: input.source.activeLeafId,
      sessionManager: input.source.sessionManager,
      now: input.now,
    });
    if (!attached.ok) {
      return attached;
    }

    const snapshot = await tempStore.openThread(attached.value.thread.threadId);
    return snapshot;
  } finally {
    await rm(tempProjectDir, { recursive: true, force: true }).catch(() => undefined);
  }
}

async function loadFixtureSnapshot(input: CreateRealSessionFixtureInput): Promise<StewardResult<ThreadSnapshot>> {
  if (input.source.type === "managed_thread") {
    return loadManagedThreadSnapshot({
      ...input,
      source: input.source,
    });
  }

  return loadPiSessionSnapshot({
    ...input,
    source: input.source,
  });
}

export async function createRealSessionFixture(
  input: CreateRealSessionFixtureInput,
): Promise<StewardResult<FixtureRecord>> {
  const snapshot = await loadFixtureSnapshot(input);
  if (!snapshot.ok) {
    return wrapFixtureFailure(input, snapshot.issues);
  }

  const fixture = buildFixtureRecord(input, snapshot.value, nowIso(input.now));
  const created = await input.store.createFixture({
    fixture,
    snapshot: snapshot.value,
  });
  if (!created.ok) {
    return wrapFixtureFailure(input, created.issues);
  }

  return ok(created.value, created.issues);
}

import {
  clonePlaceholderArtifactState,
  type PlaceholderArtifactState,
} from "./placeholder-artifact-state.js";
import type { StewardIssue } from "../../domain/errors.js";

export const CHUNK_LIFECYCLE_STATUSES = ["open", "closed"] as const;
export const CHUNK_CLOSE_REASONS = ["soft_threshold", "hard_max", "manual", "repair"] as const;

export type ChunkLifecycleStatus = (typeof CHUNK_LIFECYCLE_STATUSES)[number];
export type ChunkCloseReason = (typeof CHUNK_CLOSE_REASONS)[number];

export interface ChunkState {
  chunkId: string;
  threadId: string;
  lifecycleStatus: ChunkLifecycleStatus;
  sourceTurnIds: string[];
  smoothText?: string;
  smoothTokenCount: number;
  openedAt?: string;
  closedAt?: string;
  closeReason?: ChunkCloseReason;
  sourceRevision?: number;
  placeholders?: PlaceholderArtifactState;
}

export interface UpdateChunkStateInput {
  threadId: string;
}

export interface UpdateChunkStateResult {
  threadId: string;
  updatedChunkIds: string[];
  blockers: StewardIssue[];
}

export function cloneChunkState(record: ChunkState): ChunkState {
  return {
    ...record,
    sourceTurnIds: [...record.sourceTurnIds],
    placeholders: record.placeholders ? clonePlaceholderArtifactState(record.placeholders) : undefined,
  };
}

export interface ChunkCloseSettings {
  targetMinSmoothTokens: number;
  targetSoftMaxSmoothTokens: number;
  hardMaxSmoothTokens: number;
}

export interface PlaceholderBuildSettings {
  detailedRatio: number;
  briefRatio: number;
  detailedStrategy: "deterministic_truncate_30";
  briefStrategy: "deterministic_truncate_5";
}

export const DEFAULT_CHUNK_CLOSE_SETTINGS: ChunkCloseSettings = {
  targetMinSmoothTokens: 1_200,
  targetSoftMaxSmoothTokens: 1_800,
  hardMaxSmoothTokens: 2_200,
};

export const DEFAULT_PLACEHOLDER_BUILD_SETTINGS: PlaceholderBuildSettings = {
  detailedRatio: 0.3,
  briefRatio: 0.05,
  detailedStrategy: "deterministic_truncate_30",
  briefStrategy: "deterministic_truncate_5",
};

export function cloneChunkCloseSettings(settings: ChunkCloseSettings): ChunkCloseSettings {
  return {
    ...settings,
  };
}

export function validateChunkCloseSettings(settings: ChunkCloseSettings): string[] {
  const issues: string[] = [];

  if (!Number.isFinite(settings.targetMinSmoothTokens) || settings.targetMinSmoothTokens <= 0) {
    issues.push("targetMinSmoothTokens must be greater than 0.");
  }

  if (!Number.isFinite(settings.targetSoftMaxSmoothTokens) || settings.targetSoftMaxSmoothTokens <= 0) {
    issues.push("targetSoftMaxSmoothTokens must be greater than 0.");
  }

  if (!Number.isFinite(settings.hardMaxSmoothTokens) || settings.hardMaxSmoothTokens <= 0) {
    issues.push("hardMaxSmoothTokens must be greater than 0.");
  }

  if (settings.targetSoftMaxSmoothTokens < settings.targetMinSmoothTokens) {
    issues.push("targetSoftMaxSmoothTokens must be greater than or equal to targetMinSmoothTokens.");
  }

  if (settings.hardMaxSmoothTokens < settings.targetSoftMaxSmoothTokens) {
    issues.push("hardMaxSmoothTokens must be greater than or equal to targetSoftMaxSmoothTokens.");
  }

  return issues;
}

export function clonePlaceholderBuildSettings(
  settings: PlaceholderBuildSettings,
): PlaceholderBuildSettings {
  return {
    ...settings,
  };
}

export function validatePlaceholderBuildSettings(settings: PlaceholderBuildSettings): string[] {
  const issues: string[] = [];

  if (!Number.isFinite(settings.detailedRatio) || settings.detailedRatio <= 0 || settings.detailedRatio > 1) {
    issues.push("detailedRatio must be greater than 0 and less than or equal to 1.");
  }

  if (!Number.isFinite(settings.briefRatio) || settings.briefRatio <= 0 || settings.briefRatio > 1) {
    issues.push("briefRatio must be greater than 0 and less than or equal to 1.");
  }

  if (settings.briefRatio > settings.detailedRatio) {
    issues.push("briefRatio must be less than or equal to detailedRatio.");
  }

  if (settings.detailedStrategy !== "deterministic_truncate_30") {
    issues.push("detailedStrategy must be deterministic_truncate_30.");
  }

  if (settings.briefStrategy !== "deterministic_truncate_5") {
    issues.push("briefStrategy must be deterministic_truncate_5.");
  }

  return issues;
}

import type { MessageRecord, PartRecord } from "../../domain/records.js";
import {
  estimateDeterministicTokenCount,
  normalizeDeterministicText,
  type SmoothTurnStrategy,
} from "../domain/smooth-turn-state.js";

type SmoothSectionMarker = "user" | "assistant" | "tool" | "thinking";

interface SmoothSection {
  marker: SmoothSectionMarker;
  content: string;
}

export interface DeterministicSmoothFormatOptions {
  truncateToolTokenLimit: number;
  removeToolTokenLimit: number;
}

export interface DeterministicSmoothFormatResult {
  text: string;
  tokenCount: number;
  strategy: SmoothTurnStrategy;
}

const DEFAULT_FORMAT_OPTIONS: DeterministicSmoothFormatOptions = {
  truncateToolTokenLimit: 80,
  removeToolTokenLimit: 240,
};

function stableSerialize(value: string | Record<string, unknown>): string {
  if (typeof value === "string") {
    return value;
  }

  return JSON.stringify(sortJsonValue(value));
}

function sortJsonValue(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((entry) => sortJsonValue(entry));
  }

  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>)
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([key, entry]) => [key, sortJsonValue(entry)]),
    );
  }

  return value;
}

function classifyMarker(message: MessageRecord, part: PartRecord): SmoothSectionMarker {
  if (part.partType === "reasoning") {
    return "thinking";
  }

  if (part.partType === "tool_result" || message.messageKind === "tool_result" || message.actorType === "tool") {
    return "tool";
  }

  if (message.actorType === "human" || message.messageKind === "prompt") {
    return "user";
  }

  return "assistant";
}

function normalizeSectionContent(content: string): string {
  return normalizeDeterministicText(content);
}

function applyToolPolicy(
  content: string,
  options: DeterministicSmoothFormatOptions,
): string {
  const tokenCount = estimateDeterministicTokenCount(content);
  if (tokenCount === 0) {
    return "";
  }

  if (tokenCount > options.removeToolTokenLimit) {
    return "[tool output removed by deterministic policy]";
  }

  if (tokenCount > options.truncateToolTokenLimit) {
    const truncated = content
      .split(" ")
      .slice(0, options.truncateToolTokenLimit)
      .join(" ");
    return `${truncated} [tool output truncated by deterministic policy]`;
  }

  return content;
}

function buildSections(
  messages: readonly MessageRecord[],
  options: DeterministicSmoothFormatOptions,
): SmoothSection[] {
  const sections: SmoothSection[] = [];

  for (const message of messages) {
    const sortedParts = [...message.parts].sort((left, right) => left.partOrder - right.partOrder);
    for (const part of sortedParts) {
      let content = normalizeSectionContent(stableSerialize(part.content));
      if (content.length === 0) {
        continue;
      }

      const marker = classifyMarker(message, part);
      if (marker === "tool") {
        content = applyToolPolicy(content, options);
        if (content.length === 0) {
          continue;
        }
      }

      const previous = sections[sections.length - 1];
      if (previous && previous.marker === marker) {
        previous.content = `${previous.content}\n${content}`;
        continue;
      }

      sections.push({ marker, content });
    }
  }

  return sections;
}

export function buildSmoothTurnText(
  messages: readonly MessageRecord[],
  options: Partial<DeterministicSmoothFormatOptions> = {},
): DeterministicSmoothFormatResult {
  const resolvedOptions: DeterministicSmoothFormatOptions = {
    ...DEFAULT_FORMAT_OPTIONS,
    ...options,
  };
  const sections = buildSections(messages, resolvedOptions);

  const text = sections.map((section) => `[${section.marker}]\n${section.content}`).join("\n\n");

  return {
    text,
    tokenCount: estimateDeterministicTokenCount(text),
    strategy: "deterministic_marker_sections_v1",
  };
}

import type {
  EnsureSmoothTurnInput,
  EnsureSmoothTurnResult,
  ReadSmoothTurnStateInput,
  ReadSmoothTurnStateResult,
  SmoothTurnState,
} from "../domain/smooth-turn-state.js";
import { toTurnSmoothRecord } from "../domain/smooth-turn-state.js";
import type { ThreadSnapshot, ThreadStore } from "../../store/thread-store.js";
import type { TurnRecord } from "../../domain/records.js";
import type { DeterministicSmoothFormatOptions } from "./smooth-turn-format.js";
import { buildSmoothTurnText } from "./smooth-turn-format.js";
import { withSerializedThreadOperation } from "../../services/thread-service.js";
import { fail, ok, StewardResultError, type StewardResult } from "../../domain/errors.js";
import { estimateDeterministicTokenCount } from "../domain/smooth-turn-state.js";

export interface SmoothTurnServiceOptions {
  store: ThreadStore;
  now?: () => Date;
  formatOptions?: Partial<DeterministicSmoothFormatOptions>;
}

export interface PersistSmoothTurnStateInput {
  threadId: string;
  turnId: string;
  expectedSourceRevision: number;
  expectedMessageHighWatermark: number;
  expectedTurnsRevision: number;
  smooth: SmoothTurnState;
}

function findTurn(snapshot: ThreadSnapshot, turnId: string): TurnRecord | undefined {
  return snapshot.turns.find((turn) => turn.turnId === turnId);
}

function sortTurnMessages(snapshot: ThreadSnapshot, turn: TurnRecord) {
  const messagesById = new Map(snapshot.messages.map((message) => [message.messageId, message]));

  return turn.messageIds
    .map((messageId) => messagesById.get(messageId))
    .filter((message) => message !== undefined)
    .sort((left, right) => left.sourceOrder - right.sourceOrder);
}

function evaluateSmoothTurn(turn: TurnRecord): ReadSmoothTurnStateResult {
  const smooth = turn.smooth;
  if (!smooth) {
    return {
      turnId: turn.turnId,
      smoothStatus: "missing",
    };
  }

  if (turn.lifecycleStatus !== "closed") {
    return {
      turnId: turn.turnId,
      smoothStatus: "missing",
      smoothText: smooth.text,
      smoothTokenCount: smooth.tokenCount,
      smoothStrategy: smooth.strategy,
      generatedAt: smooth.generatedAt,
      sourceRevision: smooth.sourceRevision,
    };
  }

  if (
    smooth.status === "invalid" ||
    !smooth.text ||
    smooth.tokenCount === undefined ||
    smooth.tokenCount !== estimateDeterministicTokenCount(smooth.text) ||
    smooth.strategy !== "deterministic_marker_sections_v1" ||
    !smooth.generatedAt ||
    smooth.sourceRevision === undefined
  ) {
    return {
      turnId: turn.turnId,
      smoothStatus: "invalid",
      smoothText: smooth.text,
      smoothTokenCount: smooth.tokenCount,
      smoothStrategy: smooth.strategy,
      generatedAt: smooth.generatedAt,
      sourceRevision: smooth.sourceRevision,
    };
  }

  if (smooth.sourceRevision !== turn.sourceRevision || smooth.status === "stale") {
    return {
      turnId: turn.turnId,
      smoothStatus: "stale",
      smoothText: smooth.text,
      smoothTokenCount: smooth.tokenCount,
      smoothStrategy: smooth.strategy,
      generatedAt: smooth.generatedAt,
      sourceRevision: smooth.sourceRevision,
    };
  }

  return {
    turnId: turn.turnId,
    smoothStatus: "ready",
    smoothText: smooth.text,
    smoothTokenCount: smooth.tokenCount,
    smoothStrategy: smooth.strategy,
    generatedAt: smooth.generatedAt,
    sourceRevision: smooth.sourceRevision,
  };
}

function buildSmoothState(
  input: {
    threadId: string;
    turn: TurnRecord;
    generatedAt: string;
    formatOptions?: Partial<DeterministicSmoothFormatOptions>;
  },
  snapshot: ThreadSnapshot,
): SmoothTurnState {
  const formatted = buildSmoothTurnText(sortTurnMessages(snapshot, input.turn), input.formatOptions);

  return {
    turnId: input.turn.turnId,
    threadId: input.threadId,
    status: "ready",
    text: formatted.text,
    tokenCount: formatted.tokenCount,
    strategy: formatted.strategy,
    generatedAt: input.generatedAt,
    sourceRevision: input.turn.sourceRevision,
  };
}

async function writeSmoothTurn(
  input: {
    snapshot: ThreadSnapshot;
    turn: TurnRecord;
    smooth: SmoothTurnState;
  },
  store: ThreadStore,
): Promise<StewardResult<void>> {
  const turns = input.snapshot.turns.map((turn) =>
    turn.turnId === input.turn.turnId
      ? {
          ...structuredClone(turn),
          smooth: toTurnSmoothRecord(input.smooth),
        }
      : structuredClone(turn),
  );

  const writeResult = await store.writeTurns({
    threadId: input.snapshot.thread.threadId,
    expectedSourceRevision: input.snapshot.thread.sourceRevision,
    expectedMessageHighWatermark: input.snapshot.thread.messageHighWatermark,
    expectedTurnsRevision: input.snapshot.thread.turnsRevision,
    turns,
    turnState: input.snapshot.thread.status.turnState,
  });

  if (!writeResult.ok) {
    return fail(...writeResult.issues);
  }

  return ok(undefined);
}

async function persistSmoothTurnStateWithinSerializedThreadOperation(
  input: PersistSmoothTurnStateInput,
  store: ThreadStore,
): Promise<StewardResult<void>> {
  const snapshotResult = await store.openThread(input.threadId);
  if (!snapshotResult.ok) {
    return snapshotResult;
  }

  if (snapshotResult.value.thread.sourceRevision !== input.expectedSourceRevision) {
    return fail({
      code: "STALE_SOURCE_REVISION",
      message: `Thread ${input.threadId} source revision ${snapshotResult.value.thread.sourceRevision} does not match expected ${input.expectedSourceRevision}.`,
      threadId: input.threadId,
    });
  }

  if (snapshotResult.value.thread.messageHighWatermark !== input.expectedMessageHighWatermark) {
    return fail({
      code: "STALE_SOURCE_REVISION",
      message: `Thread ${input.threadId} message high watermark ${snapshotResult.value.thread.messageHighWatermark} does not match expected ${input.expectedMessageHighWatermark}.`,
      threadId: input.threadId,
    });
  }

  if (snapshotResult.value.thread.turnsRevision !== input.expectedTurnsRevision) {
    return fail({
      code: "STALE_SOURCE_REVISION",
      message: `Thread ${input.threadId} turns revision ${snapshotResult.value.thread.turnsRevision} does not match expected ${input.expectedTurnsRevision}.`,
      threadId: input.threadId,
      cause: "turns_revision",
    });
  }

  const turn = findTurn(snapshotResult.value, input.turnId);
  if (!turn) {
    return fail({
      code: "TURN_STATE_MISSING",
      message: `Turn ${input.turnId} was not found in thread ${input.threadId}.`,
      threadId: input.threadId,
    });
  }

  if (turn.sourceRevision !== input.smooth.sourceRevision) {
    return fail({
      code: "STALE_SOURCE_REVISION",
      message: `Turn ${input.turnId} source revision ${turn.sourceRevision} does not match smooth source revision ${input.smooth.sourceRevision}.`,
      threadId: input.threadId,
    });
  }

  return writeSmoothTurn(
    {
      snapshot: snapshotResult.value,
      turn,
      smooth: input.smooth,
    },
    store,
  );
}

function isRetryableTurnsRevisionFailure(result: StewardResult<void>): boolean {
  return (
    !result.ok &&
    result.issues.some((issue) => issue.code === "STALE_SOURCE_REVISION" && issue.cause === "turns_revision")
  );
}

async function persistSmoothTurnStateWithRetry(
  input: PersistSmoothTurnStateInput,
  store: ThreadStore,
): Promise<StewardResult<void>> {
  let nextInput = { ...input };
  let lastResult: StewardResult<void> | undefined;

  for (let attempt = 0; attempt < 3; attempt += 1) {
    const result = await persistSmoothTurnStateWithinSerializedThreadOperation(nextInput, store);
    if (result.ok) {
      return result;
    }

    lastResult = result;
    if (!isRetryableTurnsRevisionFailure(result)) {
      return result;
    }

    const latestSnapshot = await store.openThread(input.threadId);
    if (!latestSnapshot.ok) {
      return latestSnapshot;
    }

    nextInput = {
      ...nextInput,
      expectedTurnsRevision: latestSnapshot.value.thread.turnsRevision,
    };
  }

  return (
    lastResult ??
    fail({
      code: "STORE_UNAVAILABLE",
      message: `Smooth turn state for ${input.turnId} could not be persisted.`,
      threadId: input.threadId,
    })
  );
}

