export interface SmartCompactCommandDependencies {
  threadStore: ThreadStore;
  threadViewStore: ThreadViewStore;
  mutationCoordinator?: ThreadMutationCoordinator;
  piCliHarnessAdapter?: PiCliHarnessAdapter;
  piSessionSwitch?: PiCliHarnessAdapterDependencies;
  piThreadViewWriterOptions?: PiThreadViewWriterOptions;
  asyncThreadDependencies?: Omit<AsyncThreadRunDependencies, "store">;
  now?: () => Date;
}

function buildThreadViewOutputRevisionStatus(
  compactStatus: SmartCompactCommandResult["compactStatus"],
): "available" | "failed" {
  return compactStatus === "success" ? "available" : "failed";
}

function buildBlockedSmartCompactResult(
  input: SmartCompactCommandInput,
  issues: Parameters<typeof createStewardIssue>[0][],
): SmartCompactCommandResult {
  return {
    threadId: input.threadId,
    requestedLowerBound: input.requestedLowerBound,
    requestedBandPercentages: input.requestedBandPercentages,
    compactStatus: "blocked",
    blockers: issues.map((issue) => createStewardIssue(issue)),
  };
}

function compactStatusFromBuildStatus(
  status: "ready" | "blocked" | "degraded",
): SmartCompactCommandResult["compactStatus"] {
  if (status === "ready") {
    return "success";
  }

  return status;
}

function buildGeneratedOutputMetadata(input: {
  threadId: string;
  threadViewId?: string;
  generatedFilePath?: string;
  archivePath?: string;
  generatedAt: string;
  status: GeneratedOutputMetadata["status"];
  placeholderExplicit: boolean;
  issues?: GeneratedOutputMetadata["issues"];
}): GeneratedOutputMetadata {
  return {
    threadId: input.threadId,
    threadViewId: input.threadViewId,
    generatedFilePath: input.generatedFilePath,
    archivePath: input.archivePath,
    generatedAt: input.generatedAt,
    status: input.status,
    generatedSource: "thread_view",
    placeholderExplicit: input.placeholderExplicit,
    issues: input.issues?.map((issue) => createStewardIssue(issue)),
  };
}

export async function runSmartCompact(
  input: SmartCompactCommandInput,
  dependencies?: SmartCompactCommandDependencies,
): Promise<SmartCompactCommandResult> {
  const inputErrors = validateSmartCompactCommandInput(input);
  if (inputErrors.length > 0) {
    return buildBlockedSmartCompactResult(input, [
      {
        code: "INVALID_COMMAND_ARGS",
        message: `Invalid smart compact input: ${inputErrors.join(" ")}`,
        threadId: input.threadId,
      },
    ]);
  }

  if (!dependencies?.threadStore || !dependencies.threadViewStore) {
    return buildBlockedSmartCompactResult(input, [
      {
        code: "INVALID_COMMAND_ARGS",
        message: "runSmartCompact requires threadStore and threadViewStore dependencies.",
        threadId: input.threadId,
      },
    ]);
  }

  const threadSnapshotResult = await dependencies.threadStore.openThread(input.threadId);
  if (!threadSnapshotResult.ok) {
    return {
      threadId: input.threadId,
      requestedLowerBound: input.requestedLowerBound,
      requestedBandPercentages: input.requestedBandPercentages,
      compactStatus: "blocked",
      blockers: threadSnapshotResult.issues,
    };
  }

  const mutationCoordinator =
    dependencies.mutationCoordinator ?? new FileThreadMutationCoordinator(dependencies.threadStore);
  const lease = await mutationCoordinator.acquireThreadLease({
    threadId: input.threadId,
    expectedSourceRevision: threadSnapshotResult.value.thread.sourceRevision,
  });

  try {
    const readiness = await prepareAsyncThread(
      {
        threadId: input.threadId,
        mode: input.mode,
        requestedLowerBound: input.requestedLowerBound,
        requestedBandPercentages: input.requestedBandPercentages,
        requiredPlaceholderBands: {
          detailed: input.requestedBandPercentages.detailed > 0,
          brief: input.requestedBandPercentages.brief > 0,
        },
      },
      {
        store: dependencies.threadStore,
        now: dependencies.asyncThreadDependencies?.now ?? dependencies.now,
      },
    );

    if (readiness.blockers.length > 0) {
      return {
        threadId: input.threadId,
        requestedLowerBound: input.requestedLowerBound,
        requestedBandPercentages: input.requestedBandPercentages,
        compactStatus: "blocked",
        blockers: readiness.blockers,
      };
    }

    const buildResult = await buildDraftThreadView(input, {
      threadStore: dependencies.threadStore,
      threadViewStore: dependencies.threadViewStore,
      now: dependencies.now,
    });
    const compactStatus = compactStatusFromBuildStatus(buildResult.status);
    if (compactStatus !== "success") {
      if (compactStatus === "degraded") {
        await updateGeneratedThreadViewOutputMetadata({
          store: dependencies.threadStore,
          threadId: input.threadId,
          generatedOutput: buildGeneratedOutputMetadata({
            threadId: input.threadId,
            threadViewId: buildResult.draftThreadViewId,
            generatedAt: (dependencies.now ?? (() => new Date()))().toISOString(),
            status: "degraded",
            placeholderExplicit:
              input.requestedBandPercentages.detailed > 0 || input.requestedBandPercentages.brief > 0,
            issues: buildResult.blockers,
          }),
          now: dependencies.now,
        });
      }

      return {
        threadId: input.threadId,
        requestedLowerBound: input.requestedLowerBound,
        requestedBandPercentages: input.requestedBandPercentages,
        threadViewId: buildResult.draftThreadViewId,
        compactStatus,
        blockers: buildResult.blockers,
        resultingTokenCount: buildResult.resultingTokenCount,
      };
    }

    const threadViewSnapshot = await dependencies.threadViewStore.openThreadView(
      input.threadId,
      buildResult.draftThreadViewId,
    );
    if (!threadViewSnapshot.ok) {
      return {
        threadId: input.threadId,
        requestedLowerBound: input.requestedLowerBound,
        requestedBandPercentages: input.requestedBandPercentages,
        threadViewId: buildResult.draftThreadViewId,
        compactStatus: "blocked",
        blockers: threadViewSnapshot.issues,
        resultingTokenCount: buildResult.resultingTokenCount,
      };
    }

    const threadSnapshot = await dependencies.threadStore.openThread(input.threadId);
    if (!threadSnapshot.ok) {
      return {
        threadId: input.threadId,
        requestedLowerBound: input.requestedLowerBound,
        requestedBandPercentages: input.requestedBandPercentages,
        threadViewId: buildResult.draftThreadViewId,
        compactStatus: "blocked",
        blockers: threadSnapshot.issues,
        resultingTokenCount: buildResult.resultingTokenCount,
      };
    }

    const piFile = await buildPiThreadViewFile({
      threadId: input.threadId,
      threadViewId: buildResult.draftThreadViewId,
      emittedMessages: threadViewSnapshot.value.view.emittedMessages,
      sessionId: `${input.threadId}-${buildResult.draftThreadViewId}`,
      cwd: threadSnapshot.value.thread.target.cwd ?? process.cwd(),
      parentSessionId: threadSnapshot.value.thread.target.sessionId,
      generatedAt: (dependencies.now ?? (() => new Date()))().toISOString(),
    });

    let writeResult;
    try {
      writeResult = await writePiThreadViewFile(
        {
          threadId: input.threadId,
          threadViewId: buildResult.draftThreadViewId,
          file: piFile,
        },
        dependencies.piThreadViewWriterOptions,
      );
    } catch (error) {
      const writeFailedResult: SmartCompactCommandResult = {
        threadId: input.threadId,
        requestedLowerBound: input.requestedLowerBound,
        requestedBandPercentages: input.requestedBandPercentages,
        threadViewId: buildResult.draftThreadViewId,
        compactStatus: "write_failed",
        blockers: [
          createStewardIssue({
            code: "GENERATED_WRITE_FAILED",
            message: `Generated PI Thread View file could not be written for thread ${input.threadId}.`,
            threadId: input.threadId,
            cause: error instanceof Error ? error.message : String(error),
          }),
        ],
        resultingTokenCount: buildResult.resultingTokenCount,
      };
      await updateGeneratedThreadViewOutputMetadata({
        store: dependencies.threadStore,
        threadId: input.threadId,
        generatedOutput: buildGeneratedOutputMetadata({
          threadId: input.threadId,
          threadViewId: buildResult.draftThreadViewId,
          generatedAt: (dependencies.now ?? (() => new Date()))().toISOString(),
          status: "write_failed",
          placeholderExplicit: piFile.placeholderExplicit,
          issues: writeFailedResult.blockers,
        }),
        now: dependencies.now,
      });

      return writeFailedResult;
    }

    const piCliHarnessAdapter =
      dependencies.piCliHarnessAdapter ?? createPiCliHarnessAdapter(dependencies.piSessionSwitch);
    const loadResult = await piCliHarnessAdapter.loadThreadViewFile({
      threadId: input.threadId,
      threadViewId: buildResult.draftThreadViewId,
      filePath: writeResult.generatedFilePath,
    });
    const finalCompactStatus: SmartCompactCommandResult["compactStatus"] = loadResult.ok
      ? "success"
      : "reload_failed";

    await updateGeneratedThreadViewOutputMetadata({
      store: dependencies.threadStore,
      threadId: input.threadId,
      generatedFilePath: writeResult.generatedFilePath,
      generatedOutput: buildGeneratedOutputMetadata({
        threadId: input.threadId,
        threadViewId: buildResult.draftThreadViewId,
        generatedFilePath: writeResult.generatedFilePath,
        archivePath: writeResult.archivePath,
        generatedAt: (dependencies.now ?? (() => new Date()))().toISOString(),
        status: finalCompactStatus === "success" ? "available" : "reload_failed",
        placeholderExplicit: piFile.placeholderExplicit,
        issues: loadResult.ok ? [] : loadResult.issues,
      }),
      revision: {
        revisionId: createThreadViewOutputRevisionId(),
        threadId: input.threadId,
        threadViewId: buildResult.draftThreadViewId,
        targetRuntime: "pi",
        generatedFilePath: writeResult.generatedFilePath,
        createdAt: (dependencies.now ?? (() => new Date()))().toISOString(),
        sourceStateReference: threadViewSnapshot.value.view.sourceStateReference,
        status: buildThreadViewOutputRevisionStatus(finalCompactStatus),
      },
      now: dependencies.now,
    });

    return {
      threadId: input.threadId,
      requestedLowerBound: input.requestedLowerBound,
      requestedBandPercentages: input.requestedBandPercentages,
      threadViewId: buildResult.draftThreadViewId,
      generatedFilePath: writeResult.generatedFilePath,
      archivePath: writeResult.archivePath,
      compactStatus: finalCompactStatus,
      blockers: loadResult.ok ? [] : loadResult.issues,
      resultingTokenCount: buildResult.resultingTokenCount,
    };
  } finally {
    await lease.release();
  }
}

    createdAt,
    budgets,
  );

  return unwrapOrThrow(
    await dependencies.threadViewStore.createThreadView({ view: draftView }),
    `Failed to create draft Thread View for ${input.threadId}`,
  );
}

export async function buildDraftThreadView(
  input: ThreadViewBuildInputs,
  dependencies?: ThreadViewBuilderDependencies,
): Promise<ThreadViewBuildResult> {
  const inputErrors = validateThreadViewBuildInputs(input);
  if (inputErrors.length > 0) {
    throw new Error(`Invalid Thread View build inputs: ${inputErrors.join(" ")}`);
  }

  if (!dependencies?.threadStore || !dependencies.threadViewStore) {
    throw new Error("ThreadViewBuilder requires threadStore and threadViewStore dependencies.");
  }

  const materializer = dependencies.materializer ?? new ThreadViewMaterializer(dependencies.threadStore);
  const threadSnapshot = unwrapOrThrow(
    await dependencies.threadStore.openThread(input.threadId),
    `Failed to open thread ${input.threadId}`,
  );
  const chunkState = unwrapOrThrow(
    await dependencies.threadStore.readChunks(input.threadId),
    `Failed to read chunk state for ${input.threadId}`,
  );
  const orderedTurns = sortTurnsInSourceOrder(threadSnapshot.turns);
  const turnsById = new Map(orderedTurns.map((turn) => [turn.turnId, turn]));
  const messagesById = new Map(threadSnapshot.messages.map((message) => [message.messageId, message]));
  const tokenizedTurns = [...orderedTurns]
    .map((turn) => {
      const rawTokenCount = sortMessagesInSourceOrder(
        turn.messageIds
          .map((messageId) => messagesById.get(messageId))
          .filter((message): message is MessageRecord => message !== undefined),
      ).reduce((total, message) => total + estimateRawMessageTokenCount(message), 0);

      return {
        turn,
        rawTokenCount,
        smoothTokenCount: turn.smooth?.tokenCount ?? 0,
      } satisfies TokenizedTurn;
    })
    .sort((left, right) => right.turn.turnOrder - left.turn.turnOrder);
  const budgets = allocateBandBudgets(input.requestedLowerBound, input.requestedBandPercentages);
  const fullFidelitySelection = selectTurnIds(
    tokenizedTurns,
    budgets.fullFidelity,
    (candidate) => candidate.rawTokenCount,
  );
  const oldestFullFidelityTurnOrder = fullFidelitySelection.selectedTurnIds.length > 0
    ? Math.min(
        ...fullFidelitySelection.selectedTurnIds.map((turnId) => turnsById.get(turnId)?.turnOrder ?? Number.MAX_SAFE_INTEGER),
      )
    : Number.MAX_SAFE_INTEGER;
  const smoothCandidates = tokenizedTurns.filter(
    (candidate) =>
      !fullFidelitySelection.selectedTurnIds.includes(candidate.turn.turnId) &&
      candidate.turn.turnOrder < oldestFullFidelityTurnOrder &&
      candidate.smoothTokenCount > 0 &&
      candidate.turn.smooth?.text,
  );
  const smoothSelection = selectTurnIds(
    smoothCandidates,
    budgets.smooth,
    (candidate) => candidate.smoothTokenCount,
  );
  const selectedUpperTurnOrders = [...fullFidelitySelection.selectedTurnIds, ...smoothSelection.selectedTurnIds]
    .map((turnId) => turnsById.get(turnId)?.turnOrder)
    .filter((turnOrder): turnOrder is number => turnOrder !== undefined);
  const lowerBandBoundaryTurnOrder = selectedUpperTurnOrders.length > 0
    ? Math.min(...selectedUpperTurnOrders)
    : Number.MAX_SAFE_INTEGER;
  const orderedChunkCandidates = buildOrderedChunkCandidates(
    chunkState,
    turnsById,
    lowerBandBoundaryTurnOrder,
  );
  const detailedSelection = selectLowerBandChunkIds(
    orderedChunkCandidates.candidates,
    budgets.detailed,
    "detailed",
  );
  const briefSelection = detailedSelection.blockers.length > 0
    ? {
        selectedChunkIds: [],
        consumedTokenCount: 0,
        blockers: [] as StewardIssue[],
      }
    : selectLowerBandChunkIds(
        detailedSelection.remainingCandidates,
        budgets.brief,
        "brief",
      );
  const selectedDetailedChunkIds = orderSelectedChunks(
    detailedSelection.selectedChunkIds,
    orderedChunkCandidates.candidates,
  );
  const selectedBriefChunkIds = orderSelectedChunks(
    briefSelection.selectedChunkIds,
    orderedChunkCandidates.candidates,
  );
  const selectionBlockers = [
    ...orderedChunkCandidates.blockers,
    ...detailedSelection.blockers,
    ...briefSelection.blockers,
  ];

  const draftView = await openOrCreateDraftView(input, threadSnapshot.thread, budgets, dependencies);
  const orderedFullFidelityTurnIds = orderSelectedTurns(fullFidelitySelection.selectedTurnIds, orderedTurns);
  const orderedSmoothTurnIds = orderSelectedTurns(smoothSelection.selectedTurnIds, orderedTurns);
  const nextDraftView: ThreadViewRecord = {
    ...draftView,
    sourceStateReference: createSourceStateReference({
      sourceRevision: threadSnapshot.thread.sourceRevision,
      messageHighWatermark: threadSnapshot.thread.messageHighWatermark,
    }),
    fullFidelityBand: buildBandRecord("full_fidelity", orderedFullFidelityTurnIds, budgets.fullFidelity),
    smoothBand: buildBandRecord("smooth", orderedSmoothTurnIds, budgets.smooth),
    detailedBand: buildBandRecord("detailed", selectedDetailedChunkIds, budgets.detailed),
    briefBand: buildBandRecord("brief", selectedBriefChunkIds, budgets.brief),
    emittedMessages: [],
    status: "incomplete",
  };
  const materialized = unwrapOrThrow(
    await materializer.materializeThreadView({
      threadId: input.threadId,
      draftView: nextDraftView,
    }),
    `Failed to materialize draft Thread View for ${input.threadId}`,
  );
  const resultingTokenCount = materialized.emittedMessages.reduce(
    (total, message) => total + estimateMaterializedMessageTokenCount(message.content),
    0,
  );
  const thresholdBlockers: StewardIssue[] = [];
  if (fullFidelitySelection.consumedTokenCount > input.requestedLowerBound) {
    thresholdBlockers.push(
      createStewardIssue({
        code: "LOWER_THRESHOLD_UNREACHED",
        message: `Full-fidelity selection alone consumed ${fullFidelitySelection.consumedTokenCount} tokens, exceeding requested lower bound ${input.requestedLowerBound}.`,
        threadId: input.threadId,
      }),
    );
  } else if (resultingTokenCount > input.requestedLowerBound) {
    thresholdBlockers.push(
      createStewardIssue({
        code: "LOWER_THRESHOLD_UNREACHED",
        message: `Deterministic rebuild consumed ${resultingTokenCount} tokens, which is above requested lower bound ${input.requestedLowerBound}.`,
        threadId: input.threadId,
      }),
    );
  }

  const blockers = [...selectionBlockers, ...materialized.issues, ...thresholdBlockers];
  const resultStatus = inferResultStatus(blockers, resultingTokenCount, input.requestedLowerBound);
  const updatedAt = (dependencies.now ?? (() => new Date()))().toISOString();
  unwrapOrThrow(
    await dependencies.threadViewStore.updateThreadView({
      threadId: input.threadId,
      threadViewId: draftView.threadViewId,
      expectedUpdatedAt: draftView.updatedAt,
      patch: {
        sourceStateReference: nextDraftView.sourceStateReference,
        fullFidelityBand: {
          ...materialized.fullFidelityBand,
          targetTokenBudget: budgets.fullFidelity,
          renderedStatus: materialized.fullFidelityBand.renderedStatus,
        },
        smoothBand: {
          ...materialized.smoothBand,
          targetTokenBudget: budgets.smooth,
          renderedStatus: materialized.smoothBand.renderedStatus,
        },
        detailedBand: {
          ...nextDraftView.detailedBand,
          renderedStatus: selectionBlockers.length > 0 ? "blocked" : materialized.bandStatuses.detailed,
        },
        briefBand: {
          ...nextDraftView.briefBand,
          renderedStatus: selectionBlockers.length > 0 ? "blocked" : materialized.bandStatuses.brief,
        },
        emittedMessages: materialized.emittedMessages,
        status: BAND_STATUS_BY_RESULT[resultStatus],
        updatedAt,
      },
    }),
    `Failed to persist rebuilt draft Thread View ${draftView.threadViewId}`,
  );

  return {
    draftThreadViewId: draftView.threadViewId,
    status: resultStatus,
    resultingTokenCount,
    blockers,
  };
}

        }),
      );
      continue;
    }

    const placeholder = band.bandType === "detailed" ? chunk.placeholders?.detailed : chunk.placeholders?.brief;
    if (!placeholder?.text) {
      issues.push(
        createWorkbenchIssue({
          code: "WORKBENCH_ARTIFACT_MISSING",
          message: `Chunk ${chunkId} is missing the ${band.bandType} placeholder artifact required for materialization.`,
          threadId,
        }),
      );
    }
  }

  return issues;
}

function buildUpperBandMessages(input: {
  thread: ThreadRecord;
  view: ThreadViewRecord;
  turns: readonly TurnRecord[];
  messages: readonly MessageRecord[];
  fullFidelityBand: BandRecord;
  smoothBand: BandRecord;
}): {
  emittedMessages: ThreadViewMessageRecord[];
  bandStatuses: Pick<Record<BandType, BandRenderedStatus>, "full_fidelity" | "smooth">;
  issues: StewardIssue[];
} {
  const turnsById = indexTurns(input.turns);
  const messagesById = indexMessages(input.messages);
  const fullFidelityMessages: ThreadViewMessageRecord[] = [];
  const smoothMessages: ThreadViewMessageRecord[] = [];
  const issues: StewardIssue[] = [];

  input.fullFidelityBand.selectedIds.forEach((turnId, turnIndex) => {
    const turn = turnsById.get(turnId);
    if (!turn) {
      issues.push(
        createWorkbenchIssue({
          code: "WORKBENCH_SOURCE_UNIT_NOT_FOUND",
          message: `Turn ${turnId} was not found in thread ${input.thread.threadId}.`,
          threadId: input.thread.threadId,
        }),
      );
      return;
    }

    const turnMessages = sortMessagesInSourceOrder(
      turn.messageIds
        .map((messageId) => messagesById.get(messageId))
        .filter((message): message is MessageRecord => message !== undefined),
    );
    if (turnMessages.length !== turn.messageIds.length) {
      issues.push(
        createWorkbenchIssue({
          code: "THREAD_VIEW_STATE_CONFLICT",
          message: `Turn ${turn.turnId} cannot be materialized because canonical source messages are missing.`,
          threadId: input.thread.threadId,
          sourceRange: structuredClone(turn.sourceRange),
        }),
      );
      return;
    }

    turnMessages.forEach((message, messageIndex) => {
      fullFidelityMessages.push(
        buildRawTurnMessage(
          input.view.threadViewId,
          turn.turnId,
          message,
          turnIndex * 1_000 + messageIndex + 1,
        ),
      );
    });
  });

  input.smoothBand.selectedIds.forEach((turnId, turnIndex) => {
    const turn = turnsById.get(turnId);
    if (!turn) {
      issues.push(
        createWorkbenchIssue({
          code: "WORKBENCH_SOURCE_UNIT_NOT_FOUND",
          message: `Turn ${turnId} was not found in thread ${input.thread.threadId}.`,
          threadId: input.thread.threadId,
        }),
      );
      return;
    }

    if (!turn.smooth?.text) {
      issues.push(
        createWorkbenchIssue({
          code: "WORKBENCH_ARTIFACT_MISSING",
          message: `Turn ${turn.turnId} does not have a smooth representation available for the smooth band.`,
          threadId: input.thread.threadId,
          sourceRange: structuredClone(turn.sourceRange),
        }),
      );
      return;
    }

    smoothMessages.push(buildSmoothTurnMessage(input.view.threadViewId, turn, turnIndex + 1));
  });

  return {
    emittedMessages: concatenateBandMessages({
      full_fidelity: fullFidelityMessages,
      smooth: smoothMessages,
    }),
    bandStatuses: {
      full_fidelity:
        input.fullFidelityBand.selectedIds.length > 0 &&
        issues.some((issue) => issue.code === "THREAD_VIEW_STATE_CONFLICT")
          ? "blocked"
          : "ready",
      smooth:
        input.smoothBand.selectedIds.length > 0 &&
        issues.some((issue) => issue.code === "WORKBENCH_ARTIFACT_MISSING")
          ? "missing_artifacts"
          : "ready",
    },
    issues,
  };
}

function buildLowerBandMessages(input: {
  view: ThreadViewRecord;
  chunks: readonly ChunkState[];
  detailedBand: BandRecord;
  briefBand: BandRecord;
}): {
  emittedMessages: Partial<Record<BandType, ThreadViewMessageRecord[]>>;
  bandStatuses: Pick<Record<BandType, BandRenderedStatus>, "detailed" | "brief">;
} {
  const chunksById = new Map(input.chunks.map((chunk) => [chunk.chunkId, chunk]));
  const detailedMessages = input.detailedBand.selectedIds.map((chunkId, index) =>
    buildPlaceholderMessage(
      input.view.threadViewId,
      "detailed",
      chunksById.get(chunkId) as ChunkState,
      index + 1,
    ),
  );
  const briefMessages = input.briefBand.selectedIds.map((chunkId, index) =>
    buildPlaceholderMessage(
      input.view.threadViewId,
      "brief",
      chunksById.get(chunkId) as ChunkState,
      index + 1,
    ),
  );

  return {
    emittedMessages: {
      detailed: detailedMessages,
      brief: briefMessages,
    },
    bandStatuses: {
      detailed: "ready",
      brief: "ready",
    },
  };
}

export class ThreadViewMaterializer {
  constructor(private readonly threadStore: ThreadStore) {}

  async materializeThreadView(
    input: MaterializeThreadViewInput,
  ): Promise<WorkbenchResult<MaterializeThreadViewResult>> {
    const threadSnapshot = await this.threadStore.openThread(input.threadId);
    if (!threadSnapshot.ok) {
      return failWorkbenchResult(...threadSnapshot.issues);
    }

    const chunksSnapshot = await this.threadStore.readChunks(input.threadId);
    if (!chunksSnapshot.ok) {
      return failWorkbenchResult(...chunksSnapshot.issues);
    }

    const orderedTurns = sortTurnsInSourceOrder(threadSnapshot.value.turns);
    const turnsById = indexTurns(orderedTurns);
    const orderedChunks = sortChunksInSourceOrder(chunksSnapshot.value, turnsById);
    const fullFidelityValidation = validateTurnSelections(
      input.threadId,
      orderedTurns,
      input.draftView.fullFidelityBand,
    );
    const smoothValidation = validateTurnSelections(input.threadId, orderedTurns, input.draftView.smoothBand);
    const lowerBandValidation = LOWER_BAND_TYPES.flatMap((bandType) =>
      validateLowerBandSelections(input.threadId, orderedChunks, getBand(input.draftView, bandType)),
    );
    if (
      fullFidelityValidation.length > 0 ||
      smoothValidation.length > 0 ||
      lowerBandValidation.length > 0
    ) {
      return failWorkbenchResult(...fullFidelityValidation, ...smoothValidation, ...lowerBandValidation);
    }

    const fullFidelityBand = normalizeTurnBand(
      "full_fidelity",
      input.draftView.fullFidelityBand,
      orderedTurns,
    );
    const smoothBand = deriveDefaultSmoothBand(input.draftView.smoothBand, orderedTurns, fullFidelityBand);
    const detailedBand = normalizeLowerBand("detailed", input.draftView.detailedBand, orderedChunks);
    const briefBand = normalizeLowerBand("brief", input.draftView.briefBand, orderedChunks);
    const upperBandMessages = buildUpperBandMessages({
      thread: threadSnapshot.value.thread,
      view: input.draftView,
      turns: orderedTurns,
      messages: threadSnapshot.value.messages,
      fullFidelityBand,
      smoothBand,
    });
