        const band =
          bandType === "full_fidelity"
            ? view.fullFidelityBand
            : bandType === "smooth"
              ? view.smoothBand
              : bandType === "detailed"
                ? view.detailedBand
                : view.briefBand;

        return band.sourceUnitType === "turn" && band.selectedIds.includes(turnId)
          ? [{ threadViewId: view.threadViewId, state: view.state, bandType }]
